package com.bank.classic.service;

import com.bank.classic.model.Employee;
import com.bank.classic.model.Txn;
import com.bank.classic.repository.Repo;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.stream.Collectors;

public class ClassicQueryService {
    private final Repo repo;
    public ClassicQueryService(Repo repo) { this.repo = repo; }

    // Self-join: employees earning more than their manager.
    public List<String> earnMoreThanManager() {
        Map<Integer, Employee> byId = repo.employees().stream().collect(Collectors.toMap(e -> e.id, e -> e));
        List<String> result = new ArrayList<>();
        for (Employee e : repo.employees()) {
            if (e.managerId != null) {
                Employee mgr = byId.get(e.managerId);
                if (e.salary.compareTo(mgr.salary) > 0) result.add(e.name); // e.salary > m.salary
            }
        }
        return result;
    }

    // Cumulative sum: running balance ordered by date, id.
    public List<String> runningBalance() {
        List<Txn> ordered = repo.txns().stream()
                .sorted(Comparator.comparing((Txn t) -> t.date).thenComparingInt(t -> t.id))
                .collect(Collectors.toList());
        BigDecimal balance = BigDecimal.ZERO;
        List<String> lines = new ArrayList<>();
        for (Txn t : ordered) {
            balance = balance.add(t.amount);                      // SUM(amount) OVER (ORDER BY date,id)
            lines.add(t.date + "  " + t.amount + "  balance=" + balance);
        }
        return lines;
    }

    // Gaps-and-islands: longest streak of consecutive login days.
    public long longestLoginStreak() {
        List<LocalDate> days = new ArrayList<>(new TreeSet<>(repo.loginDays())); // distinct, sorted
        long best = 0, current = 0; LocalDate prev = null;
        for (LocalDate d : days) {
            current = (prev != null && ChronoUnit.DAYS.between(prev, d) == 1) ? current + 1 : 1;
            best = Math.max(best, current);
            prev = d;
        }
        return best;
    }
}
